logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_tmpA;
logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_tmpB;
logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_tmpC;
prefetch_req_t prefetch_lookup_req_tmpA;
prefetch_req_t prefetch_lookup_req_tmpB;
prefetch_req_t prefetch_lookup_req_tmpC;
logic lock_pre_dA;
logic lock_pre_dB;
logic lock_pre_dC;
logic lock_pre_qA;
logic lock_pre_qB;
logic lock_pre_qC;

logic stream_arbiter_correctable_error;
logic stream_arbiter_uncorrectable_error;

if (FETCH_PRIORITY) // FETCH_PRIORITY = 0 for DORA/relSpatz
  begin : gen_fetch_priority
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_priorityA;
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_priorityB;
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_priorityC;
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_preA;
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_preB;
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_preC;
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_fetchA;
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_fetchB;
    logic [NR_FETCH_PORTS - 1:0] prefetch_req_ready_fetchC;
    prefetch_req_t prefetch_lookup_req_preA;
    prefetch_req_t prefetch_lookup_req_preB;
    prefetch_req_t prefetch_lookup_req_preC;
    prefetch_req_t prefetch_lookup_req_fetchA;
    prefetch_req_t prefetch_lookup_req_fetchB;
    prefetch_req_t prefetch_lookup_req_fetchC;
    logic prefetch_lookup_req_valid_preA;
    logic prefetch_lookup_req_valid_preB;
    logic prefetch_lookup_req_valid_preC;
    logic prefetch_lookup_req_valid_fetchA;
    logic prefetch_lookup_req_valid_fetchB;
    logic prefetch_lookup_req_valid_fetchC;
    logic prefetch_filtered_readyA;
    logic prefetch_filtered_readyB;
    logic prefetch_filtered_readyC;
    logic fetch_filtered_readyA;
    logic fetch_filtered_readyB;
    logic fetch_filtered_readyC;
    for(genvar i = 0; i<NR_FETCH_PORTS; i++)
          begin : gen_prio
        assign prefetch_req_priorityA[i] = prefetch_reqA[i].id[2*i];
        assign prefetch_req_priorityB[i] = prefetch_reqB[i].id[2*i];
        assign prefetch_req_priorityC[i] = prefetch_reqC[i].id[2*i];
        assign prefetch_req_ready_tmpA[i] = prefetch_req_priorityA[i] ? prefetch_req_ready_fetchA[i] : prefetch_req_ready_preA[i];
        assign prefetch_req_ready_tmpB[i] = prefetch_req_priorityB[i] ? prefetch_req_ready_fetchB[i] : prefetch_req_ready_preB[i];
        assign prefetch_req_ready_tmpC[i] = prefetch_req_priorityC[i] ? prefetch_req_ready_fetchC[i] : prefetch_req_ready_preC[i];
      end
    assign prefetch_lookup_req_validA = prefetch_lookup_req_valid_preA|prefetch_lookup_req_valid_fetchA;
    assign prefetch_lookup_req_validB = prefetch_lookup_req_valid_preB|prefetch_lookup_req_valid_fetchB;
    assign prefetch_lookup_req_validC = prefetch_lookup_req_valid_preC|prefetch_lookup_req_valid_fetchC;
    assign prefetch_lookup_req_tmpA = prefetch_lookup_req_valid_fetchA&&!lock_pre_qA ? prefetch_lookup_req_fetchA : prefetch_lookup_req_preA;
    assign prefetch_lookup_req_tmpB = prefetch_lookup_req_valid_fetchB&&!lock_pre_qB ? prefetch_lookup_req_fetchB : prefetch_lookup_req_preB;
    assign prefetch_lookup_req_tmpC = prefetch_lookup_req_valid_fetchC&&!lock_pre_qC ? prefetch_lookup_req_fetchC : prefetch_lookup_req_preC;
    assign lock_pre_dA =  (lock_pre_qA|(~ prefetch_lookup_req_valid_fetchA & prefetch_lookup_req_valid_preA )) &~prefetch_lookup_req_readyA;
    assign lock_pre_dB =  (lock_pre_qB|(~ prefetch_lookup_req_valid_fetchB & prefetch_lookup_req_valid_preB )) &~prefetch_lookup_req_readyB;
    assign lock_pre_dC =  (lock_pre_qC|(~ prefetch_lookup_req_valid_fetchC & prefetch_lookup_req_valid_preC )) &~prefetch_lookup_req_readyC;
    assign prefetch_filtered_readyA =  (prefetch_lookup_req_valid_fetchA&&!lock_pre_qA) &&!(MERGE_FETCHES&&prefetch_lookup_req_preA.addr==prefetch_lookup_req_fetchA.addr) ? 1'b0 : prefetch_lookup_req_readyA;
    assign prefetch_filtered_readyB =  (prefetch_lookup_req_valid_fetchB&&!lock_pre_qB) &&!(MERGE_FETCHES&&prefetch_lookup_req_preB.addr==prefetch_lookup_req_fetchB.addr) ? 1'b0 : prefetch_lookup_req_readyB;
    assign prefetch_filtered_readyC =  (prefetch_lookup_req_valid_fetchC&&!lock_pre_qC) &&!(MERGE_FETCHES&&prefetch_lookup_req_preC.addr==prefetch_lookup_req_fetchC.addr) ? 1'b0 : prefetch_lookup_req_readyC;
    assign fetch_filtered_readyA = lock_pre_qA&&!(MERGE_FETCHES&&prefetch_lookup_req_preA.addr==prefetch_lookup_req_fetchA.addr) ? 1'b0 : prefetch_lookup_req_readyA;
    assign fetch_filtered_readyB = lock_pre_qB&&!(MERGE_FETCHES&&prefetch_lookup_req_preB.addr==prefetch_lookup_req_fetchB.addr) ? 1'b0 : prefetch_lookup_req_readyB;
    assign fetch_filtered_readyC = lock_pre_qC&&!(MERGE_FETCHES&&prefetch_lookup_req_preC.addr==prefetch_lookup_req_fetchC.addr) ? 1'b0 : prefetch_lookup_req_readyC;

    multi_accept_rr_arbTMR #(.data_t(prefetch_req_t), .NumInp(NR_FETCH_PORTS))
      i_stream_arbiter_pre (
        .clk_i(clk_i),
        .rst_ni(rst_ni),
        .flush_iA('0),
        .flush_iB('0),
        .flush_iC('0),
        .inp_data_iA(prefetch_reqA),
        .inp_data_iB(prefetch_reqB),
        .inp_data_iC(prefetch_reqC),
        .inp_valid_iA(prefetch_req_validA&~prefetch_req_priorityA),
        .inp_valid_iB(prefetch_req_validB&~prefetch_req_priorityB),
        .inp_valid_iC(prefetch_req_validC&~prefetch_req_priorityC),
        .inp_ready_oA(prefetch_req_ready_preA),
        .inp_ready_oB(prefetch_req_ready_preB),
        .inp_ready_oC(prefetch_req_ready_preC),
        .oup_data_oA(prefetch_lookup_req_preA),
        .oup_data_oB(prefetch_lookup_req_preB),
        .oup_data_oC(prefetch_lookup_req_preC),
        .oup_valid_oA(prefetch_lookup_req_valid_preA),
        .oup_valid_oB(prefetch_lookup_req_valid_preB),
        .oup_valid_oC(prefetch_lookup_req_valid_preC),
        .oup_ready_iA(prefetch_filtered_readyA),
        .oup_ready_iB(prefetch_filtered_readyB),
        .oup_ready_iC(prefetch_filtered_readyC)
      );

    multi_accept_rr_arbTMR #(.data_t(prefetch_req_t), .NumInp(NR_FETCH_PORTS))
    i_stream_arbiter_fetch (
        .clk_i(clk_i),
        .rst_ni(rst_ni),
        .flush_iA('0),
        .flush_iB('0),
        .flush_iC('0),
        .inp_data_iA(prefetch_reqA),
        .inp_data_iB(prefetch_reqB),
        .inp_data_iC(prefetch_reqC),
        .inp_valid_iA(prefetch_req_validA&prefetch_req_priorityA),
        .inp_valid_iB(prefetch_req_validB&prefetch_req_priorityB),
        .inp_valid_iC(prefetch_req_validC&prefetch_req_priorityC),
        .inp_ready_oA(prefetch_req_ready_fetchA),
        .inp_ready_oB(prefetch_req_ready_fetchB),
        .inp_ready_oC(prefetch_req_ready_fetchC),
        .oup_data_oA(prefetch_lookup_req_fetchA),
        .oup_data_oB(prefetch_lookup_req_fetchB),
        .oup_data_oC(prefetch_lookup_req_fetchC),
        .oup_valid_oA(prefetch_lookup_req_valid_fetchA),
        .oup_valid_oB(prefetch_lookup_req_valid_fetchB),
        .oup_valid_oC(prefetch_lookup_req_valid_fetchC),
        .oup_ready_iA(fetch_filtered_readyA),
        .oup_ready_iB(fetch_filtered_readyB),
        .oup_ready_iC(fetch_filtered_readyC),
        .multi_accept_rr_correctable_error_o(stream_arbiter_correctable_error),
        .multi_accept_rr_uncorrectable_error_o(stream_arbiter_uncorrectable_error)
      );

    always_ff @( posedge clk_iA or negedge rst_niA )
      begin
        if (!rst_niA)
          begin
            lock_pre_qA <= '0;
          end
        else
          begin
            lock_pre_qA <= lock_pre_dVotedA;
          end
      end

    always_ff @( posedge clk_iB or negedge rst_niB )
      begin
