        assign prefetch_req_readyB[i] = prefetch_req_ready_tmpB[i]| (prefetch_lookup_req_readyB&prefetch_reqB[i].addr==prefetch_lookup_reqB.addr) ;
        assign prefetch_req_readyC[i] = prefetch_req_ready_tmpC[i]| (prefetch_lookup_req_readyC&prefetch_reqC[i].addr==prefetch_lookup_reqC.addr) ;
      end

