    assign in_addr_maskedB[i] = {in_addr_iB[i][CFG.FETCH_AW - 1:CFG.LINE_ALIGN], {CFG.LINE_ALIGN{1'b0}}};
    assign in_addr_maskedC[i] = {in_addr_iC[i][CFG.FETCH_AW - 1:CFG.LINE_ALIGN], {CFG.LINE_ALIGN{1'b0}}};
  end

stream_arbiter #(.DATA_T(fetch_addr_t), .N_INP(CFG.NR_FETCH_PORTS)) i_stream_arbiterA (
    .clk_i(clk_iA),
    .rst_ni(rst_niA),
    .inp_data_i(in_addr_maskedA),
    .inp_valid_i(in_validA),
    .inp_ready_o(in_readyA),
    .oup_data_o(refill_req_addr_oA),
    .oup_valid_o(refill_req_valid_oA),
    .oup_ready_i(refill_req_ready_iA)
  );

stream_arbiter #(.DATA_T(fetch_addr_t), .N_INP(CFG.NR_FETCH_PORTS)) i_stream_arbiterB (
    .clk_i(clk_iB),
    .rst_ni(rst_niB),
    .inp_data_i(in_addr_maskedB),
