    .inp_data_i(in_addr_maskedC),
    .inp_valid_i(in_validC),
    .inp_ready_o(in_readyC),
    .oup_data_o(refill_req_addr_oC),
    .oup_valid_o(refill_req_valid_oC),
    .oup_ready_i(refill_req_ready_iC)
  );
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_fifo_muxA;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_fifo_muxB;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_fifo_muxC;
logic [NrFetchPortsBin - 1:0] onehot_muxA;
logic [NrFetchPortsBin - 1:0] onehot_muxB;
logic [NrFetchPortsBin - 1:0] onehot_muxC;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_fifo_popA;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_fifo_popB;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_fifo_popC;
logic rsp_fifo_fullA;
logic rsp_fifo_fullB;
logic rsp_fifo_fullC;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_validA;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_validB;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_validC;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_readyA;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_readyB;
logic [CFG.NR_FETCH_PORTS - 1:0] rsp_readyC;
logic [CFG.NR_FETCH_PORTS - 1:0] [CFG.FETCH_DW:0] rsp_qA;
logic [CFG.NR_FETCH_PORTS - 1:0] [CFG.FETCH_DW:0] rsp_qB;
logic [CFG.NR_FETCH_PORTS - 1:0] [CFG.FETCH_DW:0] rsp_qC;
logic [CFG.NR_FETCH_PORTS - 1:0] [CFG.FETCH_DW:0] rsp_nextA;
logic [CFG.NR_FETCH_PORTS - 1:0] [CFG.FETCH_DW:0] rsp_nextB;
logic [CFG.NR_FETCH_PORTS - 1:0] [CFG.FETCH_DW:0] rsp_nextC;

rel_fifo #(.DataWidth(CFG.NR_FETCH_PORTS), .Depth(4)) rsp_fifoA (
    .clk_i(clk_iA),
    .rst_ni(rst_niA),
    .flush_i(1'b0),
    .testmode_i(1'b0),
    .full_o(rsp_fifo_fullA),
    .empty_o(),
    .usage_o(),
    .data_i({in_validA&in_readyA}),
    .push_i(|{in_validA&in_readyA}),
    .data_o(rsp_fifo_muxA),
    .pop_i(|rsp_fifo_popA),
    .fault_o()
  );

rel_fifo #(.DataWidth(CFG.NR_FETCH_PORTS), .Depth(4)) rsp_fifoB (
    .clk_i(clk_iB),
    .rst_ni(rst_niB),
    .flush_i(1'b0),
    .testmode_i(1'b0),
    .full_o(rsp_fifo_fullB),
    .empty_o(),
    .usage_o(),
    .data_i({in_validB&in_readyB}),
    .push_i(|{in_validB&in_readyB}),
    .data_o(rsp_fifo_muxB),
    .pop_i(|rsp_fifo_popB),
    .fault_o()
  );

rel_fifo #(.DataWidth(CFG.NR_FETCH_PORTS), .Depth(4)) rsp_fifoC (
    .clk_i(clk_iC),
    .rst_ni(rst_niC),
    .flush_i(1'b0),
    .testmode_i(1'b0),
    .full_o(rsp_fifo_fullC),
    .empty_o(),
    .usage_o(),
    .data_i({in_validC&in_readyC}),
    .push_i(|{in_validC&in_readyC}),
    .data_o(rsp_fifo_muxC),
    .pop_i(|rsp_fifo_popC),
    .fault_o()
  );

onehot_to_bin #(.ONEHOT_WIDTH(CFG.NR_FETCH_PORTS)) i_onehot_to_binA (
    .onehot(rsp_fifo_muxA),
    .bin(onehot_muxA)
  );

onehot_to_bin #(.ONEHOT_WIDTH(CFG.NR_FETCH_PORTS)) i_onehot_to_binB (
    .onehot(rsp_fifo_muxB),
    .bin(onehot_muxB)
  );

onehot_to_bin #(.ONEHOT_WIDTH(CFG.NR_FETCH_PORTS)) i_onehot_to_binC (
    .onehot(rsp_fifo_muxC),
    .bin(onehot_muxC)
  );
assign rsp_readyA = '1;
assign rsp_readyB = '1;
assign rsp_readyC = '1;

stream_demux #(.N_OUP(CFG.NR_FETCH_PORTS)) i_stream_mux_miss_refillA (
    .inp_valid_i(refill_rsp_valid_iA),
    .inp_ready_o(refill_rsp_ready_oA),
    .oup_sel_i(onehot_muxA),
    .oup_valid_o(rsp_validA),
    .oup_ready_i(rsp_readyA)
  );

stream_demux #(.N_OUP(CFG.NR_FETCH_PORTS)) i_stream_mux_miss_refillB (
    .inp_valid_i(refill_rsp_valid_iB),
    .inp_ready_o(refill_rsp_ready_oB),
    .oup_sel_i(onehot_muxB),
    .oup_valid_o(rsp_validB),
    .oup_ready_i(rsp_readyB)
  );

stream_demux #(.N_OUP(CFG.NR_FETCH_PORTS)) i_stream_mux_miss_refillC (
    .inp_valid_i(refill_rsp_valid_iC),
    .inp_ready_o(refill_rsp_ready_oC),
    .oup_sel_i(onehot_muxC),
    .oup_valid_o(rsp_validC),
    .oup_ready_i(rsp_readyC)
  );
for(genvar i = 0; i<CFG.NR_FETCH_PORTS; i++)
  begin : gen_bypass_request

    always_comb
      begin
        state_dA[i] = state_qA[i];
        in_ready_oA[i] = 1'b0;
        rsp_fifo_popA[i] = 1'b0;
        in_validA[i] = 1'b0;
        unique case (state_qA[i])
          Idle :
            if (in_valid_iA[i])
              state_dA[i] = RequestData;

          RequestData :
            begin
              if (!rsp_fifo_fullA)
                begin
                  in_validA[i] = 1'b1;
                  if (in_readyA[i])
                    state_dA[i] = WaitResponse;

                end

            end
          WaitResponse :
            begin
              if (rsp_validA[i])
                begin
                  rsp_fifo_popA[i] = 1'b1;
                  state_dA[i] = PresentResponse;
                end

            end
          PresentResponse :
            begin
              state_dA[i] = Idle;
              in_ready_oA[i] = 1'b1;
            end
          default : ;
        endcase
      end

    always_comb
      begin
        state_dB[i] = state_qB[i];
        in_ready_oB[i] = 1'b0;
        rsp_fifo_popB[i] = 1'b0;
        in_validB[i] = 1'b0;
        unique case (state_qB[i])
          Idle :
            if (in_valid_iB[i])
              state_dB[i] = RequestData;

          RequestData :
            begin
              if (!rsp_fifo_fullB)
                begin
                  in_validB[i] = 1'b1;
                  if (in_readyB[i])
                    state_dB[i] = WaitResponse;

                end

            end
          WaitResponse :
            begin
              if (rsp_validB[i])
                begin
                  rsp_fifo_popB[i] = 1'b1;
                  state_dB[i] = PresentResponse;
                end

            end
          PresentResponse :
            begin
              state_dB[i] = Idle;
              in_ready_oB[i] = 1'b1;
            end
          default : ;
        endcase
      end

    always_comb
      begin
        state_dC[i] = state_qC[i];
        in_ready_oC[i] = 1'b0;
        rsp_fifo_popC[i] = 1'b0;
        in_validC[i] = 1'b0;
        unique case (state_qC[i])
          Idle :
            if (in_valid_iC[i])
              state_dC[i] = RequestData;

          RequestData :
            begin
              if (!rsp_fifo_fullC)
                begin
                  in_validC[i] = 1'b1;
                  if (in_readyC[i])
                    state_dC[i] = WaitResponse;

                end

            end
          WaitResponse :
            begin
              if (rsp_validC[i])
                begin
                  rsp_fifo_popC[i] = 1'b1;
                  state_dC[i] = PresentResponse;
                end

            end
          PresentResponse :
            begin
              state_dC[i] = Idle;
              in_ready_oC[i] = 1'b1;
            end
          default : ;
        endcase
      end
    logic [CFG.FILL_DW - 1:0] fill_rsp_dataA;
    logic [CFG.FILL_DW - 1:0] fill_rsp_dataB;
    logic [CFG.FILL_DW - 1:0] fill_rsp_dataC;
    assign fill_rsp_dataA = refill_rsp_data_iA>> (in_addr_iA[i][CFG.LINE_ALIGN - 1:CFG.FETCH_ALIGN]*CFG.FETCH_DW) ;
    assign fill_rsp_dataB = refill_rsp_data_iB>> (in_addr_iB[i][CFG.LINE_ALIGN - 1:CFG.FETCH_ALIGN]*CFG.FETCH_DW) ;
    assign fill_rsp_dataC = refill_rsp_data_iC>> (in_addr_iC[i][CFG.LINE_ALIGN - 1:CFG.FETCH_ALIGN]*CFG.FETCH_DW) ;
    assign rsp_nextA[i] = rsp_validA[i] ? {fill_rsp_dataA[CFG.FETCH_DW - 1:0], refill_rsp_error_iA} : rsp_qA[i];
    assign rsp_nextB[i] = rsp_validB[i] ? {fill_rsp_dataB[CFG.FETCH_DW - 1:0], refill_rsp_error_iB} : rsp_qB[i];
    assign rsp_nextC[i] = rsp_validC[i] ? {fill_rsp_dataC[CFG.FETCH_DW - 1:0], refill_rsp_error_iC} : rsp_qC[i];
    assign in_data_oA[i] = rsp_qA[i][CFG.FETCH_DW:1];
    assign in_data_oB[i] = rsp_qB[i][CFG.FETCH_DW:1];
    assign in_data_oC[i] = rsp_qC[i][CFG.FETCH_DW:1];
    assign in_error_oA[i] = rsp_qA[i][0];
    assign in_error_oB[i] = rsp_qB[i][0];
    assign in_error_oC[i] = rsp_qC[i][0];
  end

always_ff @( posedge clk_iA )
  begin
    rsp_qA <= rsp_nextVotedA;
  end

always_ff @( posedge clk_iB )
  begin
    rsp_qB <= rsp_nextVotedB;
  end

always_ff @( posedge clk_iC )
  begin
    rsp_qC <= rsp_nextVotedC;
  end

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        state_qA <= '{default: Idle};
      end
    else
      begin
        state_qA <= state_dVotedA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin
    if (!rst_niB)
      begin
        state_qB <= '{default: Idle};
      end
    else
      begin
        state_qB <= state_dVotedB;
      end
  end

always_ff @( posedge clk_iC or negedge rst_niC )
  begin
    if (!rst_niC)
      begin
        state_qC <= '{default: Idle};
      end
    else
      begin
        state_qC <= state_dVotedC;
      end
  end

majorityVoter #(.WIDTH( (((((CFG.NR_FETCH_PORTS-1)>0) ? (CFG.NR_FETCH_PORTS-1) : - ( CFG.NR_FETCH_PORTS-1 ) )+1)*((((CFG.FETCH_DW)>0) ? (CFG.FETCH_DW) : - ( CFG.FETCH_DW ) )+1)) )) rsp_nextVoterA (
    .inA(rsp_nextA),
    .inB(rsp_nextB),
    .inC(rsp_nextC),
    .out(rsp_nextVotedA),
    .tmrErr(rsp_nextTmrErrorA)
  );

majorityVoter #(.WIDTH( (2*((((CFG.NR_FETCH_PORTS-1)>0) ? (CFG.NR_FETCH_PORTS-1) : - ( CFG.NR_FETCH_PORTS-1 ) )+1)) )) state_dVoterA (
    .inA(state_dA),
    .inB(state_dB),
    .inC(state_dC),
    .out({state_dVotedA}),
    .tmrErr(state_dTmrErrorA)
  );

majorityVoter #(.WIDTH( (((((CFG.NR_FETCH_PORTS-1)>0) ? (CFG.NR_FETCH_PORTS-1) : - ( CFG.NR_FETCH_PORTS-1 ) )+1)*((((CFG.FETCH_DW)>0) ? (CFG.FETCH_DW) : - ( CFG.FETCH_DW ) )+1)) )) rsp_nextVoterB (
    .inA(rsp_nextA),
    .inB(rsp_nextB),
    .inC(rsp_nextC),
    .out(rsp_nextVotedB),
    .tmrErr(rsp_nextTmrErrorB)
  );

majorityVoter #(.WIDTH( (2*((((CFG.NR_FETCH_PORTS-1)>0) ? (CFG.NR_FETCH_PORTS-1) : - ( CFG.NR_FETCH_PORTS-1 ) )+1)) )) state_dVoterB (
    .inA(state_dA),
    .inB(state_dB),
    .inC(state_dC),
    .out({state_dVotedB}),
    .tmrErr(state_dTmrErrorB)
  );

majorityVoter #(.WIDTH( (((((CFG.NR_FETCH_PORTS-1)>0) ? (CFG.NR_FETCH_PORTS-1) : - ( CFG.NR_FETCH_PORTS-1 ) )+1)*((((CFG.FETCH_DW)>0) ? (CFG.FETCH_DW) : - ( CFG.FETCH_DW ) )+1)) )) rsp_nextVoterC (
    .inA(rsp_nextA),
    .inB(rsp_nextB),
    .inC(rsp_nextC),
    .out(rsp_nextVotedC),
    .tmrErr(rsp_nextTmrErrorC)
  );

majorityVoter #(.WIDTH( (2*((((CFG.NR_FETCH_PORTS-1)>0) ? (CFG.NR_FETCH_PORTS-1) : - ( CFG.NR_FETCH_PORTS-1 ) )+1)) )) state_dVoterC (
    .inA(state_dA),
    .inB(state_dB),
    .inC(state_dC),
    .out({state_dVotedC}),
    .tmrErr(state_dTmrErrorC)
  );

fanout clk_iFanout (
    .in(clk_i),
    .outA(clk_iA),
    .outB(clk_iB),
    .outC(clk_iC)
  );

fanout rst_niFanout (
    .in(rst_ni),
    .outA(rst_niA),
    .outB(rst_niB),
    .outC(rst_niC)
  );

assign l0_to_bypass_correctable_error_o = rsp_nextTmrErrorA | rsp_nextTmrErrorB | rsp_nextTmrErrorC | state_dTmrErrorA | state_dTmrErrorB | state_dTmrErrorC; // Placeholder, replace with actual correctable error logic
assign l0_to_bypass_uncorrectable_error_o = '0; // Placeholder

endmodule
